CREATE TABLE public.despesas_contas_bancarias_permissoes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, conta_bancaria_id uuid NOT NULL REFERENCES public.despesas_contas_bancarias(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,conta_bancaria_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.despesas_contas_bancarias_permissoes TO authenticated;
GRANT ALL ON public.despesas_contas_bancarias_permissoes TO service_role;
ALTER TABLE public.despesas_contas_bancarias_permissoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY contas_perm_admin ON public.despesas_contas_bancarias_permissoes FOR ALL TO authenticated USING (public.can_view_system(auth.uid(),'despesas') AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin'))) WITH CHECK (public.can_view_system(auth.uid(),'despesas') AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin')));
CREATE POLICY contas_perm_proprias ON public.despesas_contas_bancarias_permissoes FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.can_view_system(auth.uid(),'despesas'));
CREATE TRIGGER contas_perm_updated BEFORE UPDATE ON public.despesas_contas_bancarias_permissoes FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();
CREATE TRIGGER contas_perm_audit AFTER INSERT OR UPDATE OR DELETE ON public.despesas_contas_bancarias_permissoes FOR EACH ROW EXECUTE FUNCTION public.audit_module_changes();
CREATE FUNCTION public.despesas_conta_permitida(_user_id uuid,_conta uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.can_view_system(_user_id,'despesas') AND EXISTS(SELECT 1 FROM public.despesas_contas_bancarias_permissoes p JOIN public.despesas_contas_bancarias c ON c.id=p.conta_bancaria_id WHERE p.user_id=_user_id AND c.id=_conta AND c.is_active AND (c.centro_custo_id IS NULL OR c.centro_custo_id IN (SELECT public.despesas_centros_permitidos(_user_id)))) $$;
REVOKE ALL ON FUNCTION public.despesas_conta_permitida(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.despesas_conta_permitida(uuid,uuid) TO authenticated,service_role;
DROP POLICY despesas_conta_view ON public.despesas_contas_bancarias;
DROP POLICY despesas_conta_edit ON public.despesas_contas_bancarias;
CREATE POLICY despesas_conta_view ON public.despesas_contas_bancarias FOR SELECT TO authenticated USING(public.can_view_system(auth.uid(),'despesas') AND ((public.despesas_pode_ver_aba(auth.uid(),'cadastros') AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin'))) OR (public.despesas_conta_permitida(auth.uid(),id) AND (public.despesas_pode_ver_aba(auth.uid(),'calendario') OR public.despesas_pode_ver_aba(auth.uid(),'cadastros') OR public.despesas_pode_ver_aba(auth.uid(),'repasses')))));
CREATE POLICY despesas_conta_matriz ON public.despesas_contas_bancarias FOR SELECT TO authenticated USING(public.can_view_system(auth.uid(),'despesas') AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin')));
CREATE POLICY despesas_conta_insert ON public.despesas_contas_bancarias FOR INSERT TO authenticated WITH CHECK(public.can_view_system(auth.uid(),'despesas') AND public.despesas_pode_editar_aba(auth.uid(),'cadastros') AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin')));
CREATE POLICY despesas_conta_update ON public.despesas_contas_bancarias FOR UPDATE TO authenticated USING(public.can_view_system(auth.uid(),'despesas') AND public.despesas_pode_editar_aba(auth.uid(),'cadastros') AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin'))) WITH CHECK(public.can_view_system(auth.uid(),'despesas') AND public.despesas_pode_editar_aba(auth.uid(),'cadastros') AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin')));
CREATE POLICY despesas_conta_delete ON public.despesas_contas_bancarias FOR DELETE TO authenticated USING(public.can_view_system(auth.uid(),'despesas') AND public.despesas_pode_editar_aba(auth.uid(),'cadastros') AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin')));
CREATE FUNCTION public.despesas_contas_lookup() RETURNS TABLE(id uuid,nome text,banco text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.id,c.nome,c.banco FROM public.despesas_contas_bancarias c WHERE public.despesas_conta_permitida(auth.uid(),c.id) AND (public.despesas_pode_ver_aba(auth.uid(),'calendario') OR public.despesas_pode_ver_aba(auth.uid(),'cadastros') OR public.despesas_pode_ver_aba(auth.uid(),'repasses')) ORDER BY c.nome $$;
REVOKE ALL ON FUNCTION public.despesas_contas_lookup() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.despesas_contas_lookup() TO authenticated,service_role;
CREATE FUNCTION public.despesas_validar_conta_vinculada() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF auth.uid() IS NULL THEN IF current_user='postgres' AND (current_setting('role',true) IN ('none','service_role') OR auth.role()='service_role') THEN RETURN NEW; END IF; RAISE EXCEPTION 'Usuário não autenticado'; END IF;
 IF TG_OP='UPDATE' AND NEW.conta_bancaria_id IS NOT DISTINCT FROM OLD.conta_bancaria_id THEN RETURN NEW; END IF;
 IF NEW.conta_bancaria_id IS NULL THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='despesas_lancamentos' AND TG_OP='INSERT' AND NEW.serie_recorrencia_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.despesas_recorrencias r WHERE r.id=NEW.serie_recorrencia_id AND r.conta_bancaria_id=NEW.conta_bancaria_id AND r.centro_custo_id=NEW.centro_custo_id AND public.can_view_system(auth.uid(),'despesas') AND public.despesas_pode_editar_aba(auth.uid(),'calendario') AND r.centro_custo_id IN (SELECT public.despesas_centros_permitidos(auth.uid()))) THEN RETURN NEW; END IF;
 IF NOT public.despesas_conta_permitida(auth.uid(),NEW.conta_bancaria_id) THEN RAISE EXCEPTION 'Conta bancária não autorizada para este usuário' USING ERRCODE='42501'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER validar_conta_lancamento BEFORE INSERT OR UPDATE ON public.despesas_lancamentos FOR EACH ROW EXECUTE FUNCTION public.despesas_validar_conta_vinculada();
CREATE TRIGGER validar_conta_pagamento BEFORE INSERT OR UPDATE ON public.despesas_lancamento_pagamentos FOR EACH ROW EXECUTE FUNCTION public.despesas_validar_conta_vinculada();
CREATE TRIGGER validar_conta_recorrencia BEFORE INSERT OR UPDATE ON public.despesas_recorrencias FOR EACH ROW EXECUTE FUNCTION public.despesas_validar_conta_vinculada();
CREATE FUNCTION public.despesas_hoje() RETURNS date LANGUAGE sql STABLE SET search_path=public AS $$ SELECT (now() AT TIME ZONE 'America/Fortaleza')::date $$;
CREATE FUNCTION public.despesas_status_por_vencimento(_status text,_venc date,_pago numeric,_total numeric,_baixa date,_hoje date) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN _status IN ('cancelado','quitado','gimob') OR _baixa IS NOT NULL THEN _status WHEN coalesce(_pago,0)>0 AND coalesce(_total,0)>0 AND _pago>=_total THEN 'pago' WHEN coalesce(_pago,0)>0 THEN 'pago_parcial' WHEN _status='pago' THEN 'pago' WHEN _venc<_hoje THEN 'vencido' ELSE 'a_vencer' END $$;
CREATE FUNCTION public.despesas_normalizar_status() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.status:=public.despesas_status_por_vencimento(NEW.status,NEW.data_vencimento,NEW.valor_pago,NEW.valor_total,NEW.data_baixa_veiculo,public.despesas_hoje()); RETURN NEW; END $$;
CREATE TRIGGER trg_00_despesas_normalizar_status BEFORE INSERT OR UPDATE ON public.despesas_lancamentos FOR EACH ROW EXECUTE FUNCTION public.despesas_normalizar_status();
CREATE OR REPLACE FUNCTION public.despesas_lanc_marcar_manual() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN
 IF NEW.serie_recorrencia_id IS NOT NULL AND NEW.is_manual=false AND (NEW.data_vencimento IS DISTINCT FROM OLD.data_vencimento OR NEW.valor_total IS DISTINCT FROM OLD.valor_total OR NEW.descricao IS DISTINCT FROM OLD.descricao OR (NEW.status IS DISTINCT FROM OLD.status AND (NEW.status IN ('cancelado','quitado','gimob') OR OLD.status IN ('cancelado','quitado','gimob')))) THEN NEW.is_manual:=true; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.despesas_marcar_vencidos() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN UPDATE public.despesas_lancamentos SET status=public.despesas_status_por_vencimento(status,data_vencimento,valor_pago,valor_total,data_baixa_veiculo,public.despesas_hoje()) WHERE status IN ('a_vencer','vencido','pago_parcial') AND status IS DISTINCT FROM public.despesas_status_por_vencimento(status,data_vencimento,valor_pago,valor_total,data_baixa_veiculo,public.despesas_hoje()); GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
DO $$ DECLARE def text; BEGIN
 SELECT pg_get_functiondef('public.despesas_recalcular_lancamento(uuid)'::regprocedure) INTO def;
 def:=replace(def,'v_venc < current_date','v_venc < public.despesas_hoje()'); EXECUTE def;
 SELECT pg_get_functiondef('public.despesas_gerar_ocorrencias(uuid,date)'::regprocedure) INTO def;
 def:=replace(def,'BEGIN'||chr(10)||'  SELECT * INTO r', 'BEGIN'||chr(10)||'  IF auth.uid() IS NOT NULL AND NOT (public.can_view_system(auth.uid(),''despesas'') AND (public.despesas_pode_editar_aba(auth.uid(),''calendario'') OR public.despesas_pode_editar_aba(auth.uid(),''veiculos''))) THEN RAISE EXCEPTION ''Sem permissão para gerar recorrências''; END IF;'||chr(10)||'  SELECT * INTO r');
 def:=replace(def,'IF NOT FOUND OR NOT r.ativo THEN RETURN 0; END IF;', 'IF NOT FOUND OR NOT r.ativo THEN RETURN 0; END IF; IF auth.uid() IS NOT NULL AND r.centro_custo_id NOT IN (SELECT public.despesas_centros_permitidos(auth.uid())) THEN RAISE EXCEPTION ''Centro de custo não permitido''; END IF;'); EXECUTE def;
END $$;